import json
import os
import re
from collections import Counter

transcripts_dir = os.path.expanduser(r"~\.claude\projects\C--Users-13751")

bash_cmds = Counter()
mcp_tools = Counter()
other_tools = Counter()

for fname in sorted(os.listdir(transcripts_dir)):
    if not fname.endswith('.jsonl'):
        continue
    fpath = os.path.join(transcripts_dir, fname)
    with open(fpath, encoding='utf-8', errors='ignore') as fh:
        for line in fh:
            try:
                msg = json.loads(line)
            except:
                continue
            if msg.get('role') != 'assistant':
                continue
            for block in msg.get('message', {}).get('content', []):
                if block.get('type') != 'tool_use':
                    continue
                name = block.get('name', '')
                if name == 'Bash':
                    cmd = block.get('input', {}).get('command', '')
                    # Extract leading command token (handle chaining, env vars, etc.)
                    # Split by &&, ||, |, ; but keep the first segment
                    first = cmd.split('&&')[0].split('||')[0].split('|')[0].split(';')[0].strip()
                    # Skip env var prefixes like FOO=bar cmd
                    if '=' in first and ' ' not in first.split('=')[0]:
                        # It's probably a standalone env assignment, skip
                        pass
                    else:
                        # Get the first word (command)
                        parts = first.split()
                        if parts:
                            base_cmd = parts[0]
                            # For common tools, include subcommand
                            if base_cmd in ('git', 'gh', 'docker', 'npm', 'bun', 'cargo', 'kubectl'):
                                if len(parts) >= 2:
                                    bash_cmds[f'{base_cmd} {parts[1]} *'] += 1
                                else:
                                    bash_cmds[base_cmd] += 1
                            elif base_cmd in ('python', 'python3', 'node', 'bash', 'sh', 'npx'):
                                # Skip interpreters - don't allowlist
                                pass
                            else:
                                bash_cmds[base_cmd] += 1
                elif name.startswith('mcp__'):
                    mcp_tools[name] += 1
                else:
                    other_tools[name] += 1

print("=== BASH COMMANDS ===")
for cmd, count in bash_cmds.most_common(50):
    print(f"{count:4d}  {cmd}")

print("\n=== MCP TOOLS ===")
for tool, count in mcp_tools.most_common(20):
    print(f"{count:4d}  {tool}")

print("\n=== OTHER TOOLS ===")
for tool, count in other_tools.most_common(20):
    print(f"{count:4d}  {tool}")

