            except json.JSONDecodeError:
                continue

            tool_uses = []
            find_tool_uses(msg, tool_uses)

            for block in tool_uses:
                name = block.get('name', '')
                if name == 'Bash':
                    cmd = block.get('input', {}).get('command', '')
                    if cmd:
                        bash_raw.append(cmd)
                elif name.startswith('mcp__'):
                    mcp_raw[name] += 1
                elif name:
                    other_raw[name] += 1

# --- Process Bash commands ---

def normalize_cmd(cmd):
    """Extract the primary command from a shell command string."""
    cmd = cmd.strip()
    if not cmd:
        return None

    # Extract first pipeline/chain segment
    first = cmd.split('&&')[0].split('||')[0].split('|')[0].split(';')[0].strip()

    # Strip env var prefixes like FOO=bar
    while True:
        m = re.match(r'^[A-Za-z_][A-Za-z0-9_]*=([^\s]+)\s+(.*)', first)
        if m:
            first = m.group(2)
        else:
            break

    parts = first.split()
    if not parts:
        return None

    base = parts[0]

    # Skip interpreters/shells — arbitrary code execution risk
    SKIP = {'python', 'python3', 'node', 'bun', 'deno', 'ruby', 'perl',
            'bash', 'sh', 'zsh', 'fish', 'eval', 'exec', 'npx', 'bunx',
            'npm', 'yarn', 'pnpm', 'make', 'just', 'cargo', 'go', 'ssh',
            'sudo', 'docker', 'kubectl', 'dotnet'}
    if base in SKIP:
        return None

    if base == 'git' and len(parts) >= 2:
        return f'git {parts[1]}'
    elif base == 'gh' and len(parts) >= 2:
        return f'gh {parts[1]}'

    return base

cmd_counter = Counter()
for cmd in bash_raw:
    norm = normalize_cmd(cmd)
    if norm:
